-- SALY | OECE Socios.csv version 1 (adjunto att106893232), 2021-11-11.
-- Lote HISTORICO de candidatos: 75 propietarios, 161 empresas SALY, 195 aristas.
-- Descarga/contraste reproducidos 2026-11-23. Sin nombres, DNI ni prueba de control.
-- Fuente: https://osce-gob-pe.atlassian.net/wiki/rest/api/content/106889267/child/attachment/att106893232/download
-- El archivo fue creado 2021-11-11; la fecha de la carga NO prueba vigencia societaria.
-- Una sola migracion; aplicar exclusivamente mediante PR + Merge Train.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='120s';
DO $pre$
BEGIN
 IF to_regclass('saly.ventas_vinculos_empresariales_v1') IS NULL
 OR to_regclass('saly.ventas_vinculos_evidencias_v1') IS NULL
 THEN RAISE EXCEPTION 'OECE_SALY_LINK_TABLES_MISSING'; END IF;
 IF EXISTS (SELECT 1 FROM saly.ventas_vinculos_empresariales_v1
  WHERE fuente_id='PE-OECE-RNP-SOCIOS' AND fuente_version='att106893232:v1:2021-11-11')
 THEN RAISE EXCEPTION 'OECE_SALY_SOURCE_ALREADY_LOADED'; END IF;
END $pre$;
CREATE TEMP TABLE oece_socios_saly_lote (
 empresa_ruc text NOT NULL CHECK (empresa_ruc ~ '^20[0-9]{9}$'),
 propietario_ruc text NOT NULL CHECK (propietario_ruc ~ '^20[0-9]{9}$'),
 fila_origen integer NOT NULL CHECK (fila_origen>=2),
 PRIMARY KEY (empresa_ruc,propietario_ruc)
) ON COMMIT DROP;
DO $counts$
BEGIN
 IF (SELECT count(*) FROM oece_socios_saly_lote) <> 195
 OR (SELECT count(DISTINCT empresa_ruc) FROM oece_socios_saly_lote) <> 161
 OR (SELECT count(DISTINCT propietario_ruc) FROM oece_socios_saly_lote) <> 75
 OR EXISTS (SELECT 1 FROM oece_socios_saly_lote WHERE empresa_ruc=propietario_ruc)
 THEN RAISE EXCEPTION 'OECE_CANDIDATE_DATASET_INTEGRITY_FAILED'; END IF;
END $counts$;
SELECT empresa_ruc,propietario_ruc,'SOCIO_DECLARADO','CANDIDATO',
 'PE-OECE-RNP-SOCIOS','att106893232:v1:2021-11-11',DATE '2021-11-11'
FROM oece_socios_saly_lote;
SELECT v.id,'OECE:att106893232:line:'||s.fila_origen::text,
 'https://osce-gob-pe.atlassian.net/wiki/rest/api/content/106889267/child/attachment/att106893232/download',s.fila_origen,'DECLARACION_RNP',
 'NO_DETERMINADOS','Socios.csv v1; fecha archivo 2021-11-11; CANDIDATO, sin control acreditado'
FROM oece_socios_saly_lote s
JOIN saly.ventas_vinculos_empresariales_v1 v
 ON v.empresa_ruc=s.empresa_ruc AND v.vinculada_ruc=s.propietario_ruc
 AND v.tipo_relacion='SOCIO_DECLARADO' AND v.fuente_id='PE-OECE-RNP-SOCIOS'
 AND v.fuente_version='att106893232:v1:2021-11-11' AND v.fuente_corte=DATE '2021-11-11';
DO $verify$
BEGIN
 IF (SELECT count(*) FROM saly.ventas_vinculos_empresariales_v1
  WHERE fuente_id='PE-OECE-RNP-SOCIOS' AND fuente_version='att106893232:v1:2021-11-11')<>195
 OR (SELECT count(DISTINCT empresa_ruc) FROM saly.ventas_vinculos_empresariales_v1
  WHERE fuente_id='PE-OECE-RNP-SOCIOS' AND fuente_version='att106893232:v1:2021-11-11')<>161
 OR (SELECT count(DISTINCT vinculada_ruc) FROM saly.ventas_vinculos_empresariales_v1
  WHERE fuente_id='PE-OECE-RNP-SOCIOS' AND fuente_version='att106893232:v1:2021-11-11')<>75
 OR (SELECT count(*) FROM saly.ventas_vinculos_evidencias_v1 e
  JOIN saly.ventas_vinculos_empresariales_v1 v ON v.id=e.vinculo_id
  WHERE v.fuente_id='PE-OECE-RNP-SOCIOS' AND v.fuente_version='att106893232:v1:2021-11-11')<>195
 OR EXISTS (SELECT 1 FROM saly.ventas_vinculos_empresariales_v1 v
  WHERE v.fuente_id='PE-OECE-RNP-SOCIOS' AND v.fuente_version='att106893232:v1:2021-11-11'
  AND (v.estado<>'CANDIDATO' OR v.tipo_relacion<>'SOCIO_DECLARADO'))
 THEN RAISE EXCEPTION 'OECE_SALY_IMPORT_READBACK_MISMATCH'; END IF;
END $verify$;
COMMIT;
